function Logo({
  className,
  color,
  plate,
  mark,
  ink = "#fff",
}: {
  className?: string;
  color: string;
  plate: string;
  mark: string;
  ink?: string;
}) {
  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={className ?? "size-3.5"}>
      {color !== "currentColor" ? <path fill={ink} d={plate} /> : null}
      <path fill={color} d={mark} />
    </svg>
  );
}

function VbMark({ color, className }: { color: string; className?: string }) {
  const id = useId().replace(/:/g, "");
  const mono = color === "currentColor";
  const letters = (
    <text
      x="12"
      y="12.8"
      textAnchor="middle"
      dominantBaseline="central"
      fill={mono ? "#000" : "#fff"}
      fontSize="10"
      fontWeight="700"
      fontFamily="Segoe UI, ui-sans-serif, system-ui, sans-serif"
    >
      VB
    </text>
  );

  return (
    <svg viewBox="0 0 24 24" aria-hidden="true" className={className ?? "size-3.5"}>
      {mono ? (
        <>
          <mask id={id}>
            <rect width="24" height="24" fill="#fff" />
            {letters}
          </mask>
          <rect x="2" y="2" width="20" height="20" rx="4" fill={color} mask={`url(#${id})`} />
        </>
      ) : (
        <>
          <rect x="2" y="2" width="20" height="20" rx="4" fill={color} />
          {letters}
        </>
      )}
    </svg>
  );
}

function Mark({
  children,
  className,
  color,
  filled = true,
}: SVGProps<SVGSVGElement> & { children: ReactNode; color: string; filled?: boolean }) {
  return (
    <svg
      viewBox="0 0 24 24"
      aria-hidden="true"
      className={className ?? "size-3.5"}
      fill={filled ? color : "none"}
      stroke={filled ? "none" : color}
      strokeWidth={filled ? undefined : 1.8}
      strokeLinecap="round"
      strokeLinejoin="round"
    >
      {children}
    </svg>
  );
}

